add_action( 'woocommerce_admin_order_data_after_order_details', 'perfectpixel_disable_emails_checkbox' );
add_action( 'woocommerce_process_shop_order_meta', 'perfectpixel_disable_emails_save', 5 );

foreach ( array( 'customer_on_hold_order', 'customer_processing_order', 'customer_completed_order', 'customer_refunded_order', 'customer_partially_refunded_order', 'customer_note' ) as $perfectpixel_email_id ) {
	add_filter( 'woocommerce_email_recipient_' . $perfectpixel_email_id, 'perfectpixel_disable_emails_recipient', 99, 2 );
}

function perfectpixel_disable_emails_checkbox( $order ) {
	echo '<p class="form-field form-field-wide"><label><input type="checkbox" name="perfectpixel_disable_emails" value="1" ' . checked( 'yes', $order->get_meta( '_perfectpixel_disable_emails' ), false ) . '> Χωρίς emails στον πελάτη για αυτή την παραγγελία</label></p>';
}

// Priority 5: saved before WooCommerce changes the status (and sends emails) in the same request.
function perfectpixel_disable_emails_save( $order_id ) {
	if ( ! current_user_can( 'edit_shop_orders' ) ) {
		return;
	}
	$order = wc_get_order( $order_id );
	if ( $order ) {
		$order->update_meta_data( '_perfectpixel_disable_emails', empty( $_POST['perfectpixel_disable_emails'] ) ? 'no' : 'yes' );
		$order->save_meta_data();
	}
}

function perfectpixel_disable_emails_recipient( $recipient, $order ) {
	return ( $order instanceof WC_Order && 'yes' === $order->get_meta( '_perfectpixel_disable_emails' ) ) ? '' : $recipient;
}
